-- ==========================================================================
-- B4 FOLLOW-ON FIX (waterflood): waterflood: one duplicate rewrite
--
-- Courses: waterflood. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/waterflood.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql waterflood. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- waterflood intermediate final - ord 21
  select case when md5(prompt) = 'a68e1da2423dd2fcdb87f74fcd96adf9' and md5(coalesce(explanation, '')) = 'ce0d7487f5f39af44884705a6cccc743' and md5(options::text) = md5('["A belief that one element is less connected belongs in the allocation matrix, which already encodes it once.", "Applying two targets means running the scale rule twice, which compounds the proportional correction.", "A differentiated target changes the rolling window as well as the scale.", "The clamp is applied per element, so two targets mean two clamps and an element can be limited twice."]'::jsonb::text) and answer_index = 0 then 'old'
              when md5(prompt) = '577a039d2b874896cc922e224b484c07' and md5(coalesce(explanation, '')) = '676313eeb24303984d48a1ed8f5c113f' and md5(options::text) = md5('["Because Ekene-4 is the well whose injectivity degrades, and a target that cannot be delivered is not a target.", "Because the clamp caps the South scale at 2.0, so Ekene-4 cannot lift the element to the target.", "Because Ekene-4 has never produced water, so the flood response there is unproven.", "Because the scale rule already caps Ekene-4 at its Hall slope limit, so the rest falls short."]'::jsonb::text) and answer_index = 0 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'waterflood' and tier = 'intermediate' and scope = 'final' and module_key is not distinct from null and ord = 21 and active;
  if v_state is null then raise exception 'B4 fix waterflood refused: no row for waterflood intermediate final - ord 21'; end if;
  if v_state = 'other' then raise exception 'B4 fix waterflood refused: waterflood intermediate final - ord 21 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'Holding the South element at the field target means sending much more water through Ekene-4. Why does the lesson count that as an argument for a separate South target?', options = '["Because Ekene-4 is the well whose injectivity degrades, and a target that cannot be delivered is not a target.", "Because the clamp caps the South scale at 2.0, so Ekene-4 cannot lift the element to the target.", "Because Ekene-4 has never produced water, so the flood response there is unproven.", "Because the scale rule already caps Ekene-4 at its Hall slope limit, so the rest falls short."]'::jsonb,
           answer_index = 0, explanation = 'This is the deliverability argument: increasing the South element means pushing harder on Ekene-4, the well whose injectivity degrades, and a target that cannot be delivered is not a target. At 1.05 the South scale is 1.726255853400599, inside the clamp; the scale rule knows nothing about injectivity; and the well that has never produced water is the producer Ekene-5.'
     where app_slug = 'waterflood' and tier = 'intermediate' and scope = 'final' and module_key is not distinct from null and ord = 21 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix waterflood refused: waterflood intermediate final - ord 21 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'waterflood' and active;
  if v_total <> 396 then raise exception 'B4 fix waterflood refused: waterflood holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix waterflood: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
